// ---------------------------------------------------------------------------
// Frozen Single Round and Single Arch — STYLE reference images.
//
// 2026-10-22. "neden referanstakinin exactly same yapamiyorsun?" The round's
// garland is already that photo replayed balloon for balloon in the layout
// guide, but the room, the daylight, the balloons' finish and the flat cut
// lettering are things words kept missing. The photo itself is handed to the
// model as IMAGE 2 (the flux-2 edit models take several image_urls): image 1
// — the guide — still fixes where everything stands; image 2 shows how it all
// looks. Tested on three seeds: room, light, fullness and lettering matched
// the photo, and the plinth held on all three once the opening sentence named
// it. Frozen only — the photo is a Frozen palette, and its blue and lilac would
// bleed into any other.
//
// The customer's reference photo, 720px wide, as a JPEG data URI.
export const ROUND_STYLE_REFERENCE: string =
  "data:image/jpeg;base64,";

// 2026-10-22: the Frozen lone arch likewise, against its reference photo
// ("balonlar referanstakinin aynisi olsun ... gun isigi biraz daha sicaklik
// var ... referanstaki ferahligi yakalayalim"). 640px wide.
export const ARCH_STYLE_REFERENCE: string =
  "data:image/jpeg;base64,";

// 2026-10-22: and the Frozen lone banner, against its reference photo (the
// castle print with the garland over the top right corner). 720px wide.
export const BANNER_STYLE_REFERENCE: string =
  "data:image/jpeg;base64,";

// 2026-10-22: and the Frozen Shimmer Wall and Arch + Shimmer, against theirs
// ("referanstaki netlik yok bizim renderda"): big crisp sequin discs, a lit
// warm-white LED neon "Happy Birthday", two full garland columns. 840px wide.
export const SHIMMER_STYLE_REFERENCE: string =
  "data:image/jpeg;base64,";
export const ARCH_SHIMMER_STYLE_REFERENCE: string =
  "data:image/jpeg;base64,";

// 2026-10-22: and the Frozen Triple Arch, against its reference: without it
// the render read the three boards as one balloon arch ("balonlar backdropu
// sarmis"). 900px wide.
export const TRIPLE_STYLE_REFERENCE: string =
  "data:image/jpeg;base64,";

// 2026-10-22: a close-up of that reference's right-hand garland, for the
// Double Arch — "double backdrop triple gibi isik ayni sicaklikta olsun". A
// close-up, not the whole photo: the whole photo has three boards. 330x640.
export const TRIPLE_GARLAND_CLOSEUP: string =
  "data:image/jpeg;base64,";

/**
 * The style reference a scene is shot against, if any — Frozen, with
 * balloons: a lone round, arch, banner or shimmer wall, an arch beside a
 * shimmer wall, the Double Arch (a close-up only) or the Triple Arch. `board` names the pieces in the prompt, `light` the daylight.
 */
export function sceneStyleReference(scene: { theme?: string; panels: { type: string }[]; balloons?: { style?: string } }):
  { image: string; board: string; light: string; closeUp?: boolean } | null {
  if (String(scene.theme ?? "").toLowerCase() !== "frozen") return null;
  if ((scene.balloons?.style ?? "none") === "none") return null;
  const types = scene.panels.map((p) => p.type);
  if (types.length === 2 && types.includes("arch") && types.includes("shimmer_wall")) {
    return { image: ARCH_SHIMMER_STYLE_REFERENCE, board: "arch board, the shimmer wall", light: "soft daylight" };
  }
  if (types.length === 3 && types.filter((t) => t === "half_arch").length === 2 && types.includes("arch")) {
    // 2026-10-22 (later): the close-up, not the whole photo — the whole photo
    // brought its own rounded side boards and fluted plinth into the render.
    void TRIPLE_STYLE_REFERENCE;
    return { image: TRIPLE_GARLAND_CLOSEUP, board: "three boards", light: "soft warm daylight", closeUp: true };
  }
  if (types.length === 2 && types.every((t) => t === "arch")) {
    return { image: TRIPLE_GARLAND_CLOSEUP, board: "two arch boards", light: "soft warm daylight", closeUp: true };
  }
  if (types.length !== 1) return null;
  const t = types[0];
  if (t === "round") return { image: ROUND_STYLE_REFERENCE, board: "round board", light: "soft daylight" };
  if (t === "arch") return { image: ARCH_STYLE_REFERENCE, board: "arch board", light: "warm, airy soft daylight" };
  if (t === "banner") return { image: BANNER_STYLE_REFERENCE, board: "square banner board", light: "warm, airy soft daylight" };
  if (t === "shimmer_wall") return { image: SHIMMER_STYLE_REFERENCE, board: "shimmer wall", light: "soft daylight" };
  return null;
}
